mapper.select:
SELECT e.event_id, e.title, e.event_type, e.sigungu, e.place_name, e.lat, e.lng, e.start_date, e.end_date, e.apply_start, e.apply_end, e.target, e.distances, e.fee_text, e.contact, e.homepage_url, e.collected_at,
FROM events e WHERE
/* 마감 임박순 */ ORDER BY CASE applyState WHEN 'OPEN' THEN 0 WHEN 'UNKNOWN' THEN 1 WHEN 'BEFORE' THEN 2 ELSE 3 END, (e.apply_end IS NULL), e.apply_end, e.start_date
/* 가까운 순 (기본). 가깝더라도 접수가 끝났으면 맨 아래로 내림 */ ORDER BY (applyState = 'CLOSED'), distanceKm, e.start_date
